 Then carefully remove from the mold. Dust with some icing sugar and serve. Enjoy your meal!	1	\N	Polish	["╨┐╨╡╤А╨╡╨║╤Г╤Б"]	t	https://www.bbcgoodfood.com/recipes/mini-bundt-cakes	mealdb:53304	[{"id": "55ae4a63-2b9c-4d3b-8ad4-a2208d4c36bd", "name": "╨Ь╨░╤Б╨╗╨╛", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "1338b99b-c8f0-44df-af06-d78808709d42", "originalString": "50 ╨│"}, {"id": "3398d1ef-8780-4221-aa19-20f37ea37f34", "name": "╨Я╤И╨╡╨╜╨╕╤З╨╜╨░╤П ╨╝╤Г╨║╨░", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "89fd83a9-9424-4975-a81b-218d640c70a2", "originalString": "50 ╨│"}, {"id": "d26bf3a6-6c85-42af-824d-01cc735d7bc3", "name": "╨б╨░╤Е╨░╤А╨╜╨░╤П ╨┐╤Г╨┤╤А╨░", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "0ae3eca4-e36e-42f4-ae8e-a3f42bcb8501", "originalString": "50 ╨│"}, {"id": "a6b7e245-36d4-4eda-b9e3-fff7d43151bb", "name": "╨п╨╣╤Ж╨╛", "unit": "╨│", "grams": 150, "amount": 150, "ingredientId": "cab42edd-5e3a-4893-839e-9f4ef50c6cf0", "originalString": "150 ╨│"}, {"id": "5f872e0f-95a3-46c5-a35f-5c343b4a988c", "name": "╨а╨░╨╖╤А╤Л╤Е╨╗╨╕╤В╨╡╨╗╤М", "unit": "╨│", "grams": 5, "amount": 5, "ingredientId": "972b3e3a-16f2-4ec2-b5e3-2bd543cca16d", "originalString": "5 ╨│"}, {"id": "fa35ea5a-ff9a-494a-af86-68f3af4443d0", "name": "╨Ъ╨░╨║╨░╨╛ ╨┐╨╛╤А╨╛╤И╨╛╨║", "unit": "╨│", "grams": 10, "amount": 10, "ingredientId": "84ddbc48-7be1-43c6-ac4c-af1e76a7172d", "originalString": "10 ╨│"}, {"id": "f042faaa-0fdc-4bef-a704-d5b78d1ee320", "name": "╨Ь╨╛╨╗╨╛╨║╨╛", "unit": "╨╝╨╗", "grams": 45, "amount": 45, "ingredientId": "d106cc74-1977-4922-ba5e-2a79a179b0ab", "originalString": "45 ╨╝╨╗"}, {"id": "b35b525a-d91a-4f53-a743-2940e2457189", "name": "╨б╨░╤Е╨░╤А╨╜╨░╤П ╨┐╤Г╨┤╤А╨░", "unit": "╨│", "grams": 15, "amount": 15, "ingredientId": "0ae3eca4-e36e-42f4-ae8e-a3f42bcb8501", "originalString": "15 ╨│"}]	["vegetarian", "lactose-free", "gluten-free"]
