.	1	\N	France	["╤Г╨╢╨╕╨╜"]	t	https://www.bbcgoodfood.com/recipes/1669/ultimate-french-omelette	mealdb:52915	[{"id": "a1f38f4b-5bfc-4a89-8fed-2999c262cd78", "name": "╨п╨╣╤Ж╨░", "unit": "╤И╤В", "grams": 150, "amount": 3, "ingredientId": "2fc401b0-e772-47dd-bd82-3638f892a36d", "originalString": "3 ╤И╤В"}, {"id": "0940f9d2-b197-4397-8505-23862306bbd2", "name": "╨Ь╨░╤Б╨╗╨╛", "unit": "╨│", "grams": 20, "amount": 20, "ingredientId": "1338b99b-c8f0-44df-af06-d78808709d42", "originalString": "20 ╨│"}, {"id": "91664213-c361-4401-a428-93dbf544cc46", "name": "╨Я╨╡╤В╤А╤Г╤И╨║╨░", "unit": "╨│", "grams": 30, "amount": 30, "ingredientId": "6f6bca24-b7e6-4c6a-9f84-86fb3e2c9dcd", "originalString": "30 ╨│"}, {"id": "0b321a60-5506-4a8b-98c1-f512c9d558a0", "name": "╨и╨╜╨╕╤В╤В-╨╗╤Г╨║", "unit": "╨│", "grams": 30, "amount": 30, "ingredientId": "046429c3-27a6-4d6a-871f-9d20d9c127f7", "originalString": "30 ╨│"}, {"id": "aed2419c-0109-4405-b66f-5f579b91802f", "name": "╨н╤Б╤В╤А╨░╨│╨╛╨╜", "unit": "╨│", "grams": 15, "amount": 15, "ingredientId": "7ae6e395-7e74-492e-befe-5ed496f76c3c", "originalString": "15 ╨│"}, {"id": "c80350f0-d997-4d21-99aa-a03498776d46", "name": "╨Я╨░╤А╨╝╨╡╨╖╨░╨╜", "unit": "╨│", "grams": 5, "amount": 5, "ingredientId": "06d99240-143a-4726-b042-f917fb0503d7", "originalString": "5 ╨│"}, {"id": "f6a1af13-a864-4589-a268-d0d45ee75c09", "name": "╨У╤А╤О╨╣╨╡╤А", "unit": "╨│", "grams": 30, "amount": 30, "ingredientId": "c88faa2f-4284-4438-96e2-dffd6e511387", "originalString": "30 ╨│"}]	["vegetarian", "lactose-free"]
