o it wonтАЩt get dry.	1	\N	Egyptian	["╨┐╨╡╤А╨╡╨║╤Г╤Б"]	t	https://amiraspantry.com/egyptian-feteer-meshaltet/	mealdb:53030	[{"id": "31e70621-be39-496b-91eb-68bb6ef9e441", "name": "╨Ь╤Г╨║╨░", "unit": "╨│", "grams": 960, "amount": 960, "ingredientId": "6b9d37d6-50b6-41f6-bc22-2376d8109821", "originalString": "960 ╨│"}, {"id": "1b594294-670f-42e5-a7d1-f3b092613029", "name": "╨Т╨╛╨┤╨░", "unit": "╨╝╨╗", "grams": 360, "amount": 360, "ingredientId": "1eec42eb-3a97-4791-8cb2-da60cef6bc13", "originalString": "360 ╨╝╨╗"}, {"id": "3da9a18c-6221-412b-a768-cb9e3d31cab6", "name": "╨б╨╛╨╗╤М", "unit": "╨│", "grams": 1.3, "amount": 1.3, "ingredientId": "3789cffa-31e4-49d0-bca4-aded4002f42c", "originalString": "1.3 ╨│"}, {"id": "f56e7a22-a4d0-4441-9177-f95f752b7fe3", "name": "╨Э╨╡╤Б╨╛╨╗╨╡╨╜╨╛╨╡ ╨╝╨░╤Б╨╗╨╛", "unit": "╨│", "grams": 240, "amount": 240, "ingredientId": "c9dbd04a-52f8-4254-a987-2f747615da0b", "originalString": "240 ╨│"}, {"id": "52918f8f-43d3-4077-a8b2-21a2b8a587bb", "name": "╨Ю╨╗╨╕╨▓╨║╨╛╨▓╨╛╨╡ ╨╝╨░╤Б╨╗╨╛", "unit": "╨│", "grams": 60, "amount": 60, "ingredientId": "bbc2d001-a24b-49ee-b8ec-16e74e7297ef", "originalString": "60 ╨│"}]	["vegetarian"]
