he foil and paper, and thickly slice to serve.	1	\N	British	["╨┐╨╡╤А╨╡╨║╤Г╤Б"]	t	https://www.bbcgoodfood.com/recipes/13354/jam-rolypoly	mealdb:52890	[{"id": "0e6fafbd-305b-445d-8e44-872d59c9d2cf", "name": "╨Ь╨░╤Б╨╗╨╛", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "1338b99b-c8f0-44df-af06-d78808709d42", "originalString": "50 ╨│"}, {"id": "c860410c-0411-431a-b131-746556c74dfb", "name": "╨Ь╤Г╨║╨░ ╤Б ╤А╨░╨╖╤А╤Л╤Е╨╗╨╕╤В╨╡╨╗╨╡╨╝", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "2e0dba19-7842-4b59-afdb-1f9ca1518136", "originalString": "50 ╨│"}, {"id": "66a53211-80fc-46f7-a08c-d50dcbc79802", "name": "╨Т╨░╨╜╨╕╨╗╤М", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "146f046f-d1cd-40c1-95f9-f1f1ccdfec5e", "originalString": "50 ╨│"}, {"id": "a060a10a-719a-4200-8305-015544ec26ad", "name": "╨б╤Г╤Н╤В", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "1e5b94c0-2714-459c-8460-69905f2e3690", "originalString": "50 ╨│"}, {"id": "60763f86-dd95-4564-8445-da9d579c186c", "name": "╨Ь╨╛╨╗╨╛╨║╨╛", "unit": "╨╝╨╗", "grams": 50, "amount": 50, "ingredientId": "d106cc74-1977-4922-ba5e-2a79a179b0ab", "originalString": "50 ╨╝╨╗"}, {"id": "458dd2e3-d27c-498f-8d07-3eb35857ecf5", "name": "╨Ь╨░╨╗╨╕╨╜╨╛╨▓╨╛╨╡ ╨▓╨░╤А╨╡╨╜╤М╨╡", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "332da740-1316-4b62-9549-09e82f5a1541", "originalString": "50 ╨│"}, {"id": "3e4086cb-9ec7-4dcf-97ba-f380e9b67b07", "name": "╨Ъ╤А╨╡╨╝-╨▒╤А╤О╨╗╨╡", "unit": "╨│", "grams": 50, "amount": 50, "ingredientId": "213d6566-ac19-4513-90a3-a58f09e1194f", "originalString": "50 ╨│"}]	["vegetarian", "lactose-free"]
